docutils.utils.__init__.get_source_line:
def get_source_line(node) -> tuple[(StrPath | None, int | None)]:
    """
    Return the "source" and "line" attributes from the `node` given or from
    its closest ancestor.
    """
    while node:
        if (node.source or node.line):
            return (node.source, node.line)
        node = node.parent
    return (None, None)

docutils.parsers.rst.directives.__init__:
def unchanged_required(argument: str) -> str:
    """
    Return the argument text, unchanged.

    Directive option conversion function for options that require a value.

    Raise ``ValueError`` if no argument is found.
    """
    if argument is None:
        raise ValueError('argument required but none supplied')
    else:
        return argument

docutils.utils.__init__.find_file_in_dir:
def find_file_in_dirs(path: StrPath, dirs: Iterable[StrPath]) -> str:
    """
    Search for `path` in the list of directories `dirs`.

    Return the first expansion that matches an existing file.
    """
    path = Path(path)
    if path.is_absolute():
        return path.as_posix()
    for d in dirs:
        f = Path(d).expanduser() / path
        if f.exists():
            return f.as_posix()
    return path.as_posix()

docutils.parsers.rst.directives.__init__:
def parser_name(argument: str) -> type[parsers.Parser]:
    """
    Return a docutils parser whose name matches the argument.
    (Directive option conversion function.)

    Return `None`, if the argument evaluates to `False`.
    Raise `ValueError` if importing the parser module fails.
    """
    if not argument:
        return None
    try:
        return parsers.get_parser_class(argument)
    except ImportError as err:
        raise ValueError(str(err))

