def rst2something(writer, documenttype, doc_path='') -> None:
    description = f'Generate {documenttype} documents from standalone reStructuredText sources <https://docutils.sourceforge.io/docs/{doc_path}>.  ' + default_description
    try:
        locale.setlocale(locale.LC_ALL, '')
    except locale.Error as e:
        sys.stderr.write(f'WARNING: Cannot set the default locale: {e}.\n')
    publish_cmdline(writer=writer, description=description)

docutils.nodes.validate_yesorno:
def validate_yesorno(value: str | int | bool) -> bool:
    """Validate a `%yesorno`__ (flag) value.

    The string literal "0" evaluates to ``False``, all other
    values are converterd with `bool()`.

    __ https://docutils.sourceforge.io/docs/ref/doctree.html#yesorno
    """
    if value == '0':
        return False
    return bool(value)

docutils.utils.__init__.xml_declaration:
def xml_declaration(encoding: str | Literal['unicode'] | None = None) -> str:
    """Return an XML text declaration.

    Include an encoding declaration, if `encoding`
    is not 'unicode', '', or None.
    """
    if (encoding and encoding.lower() != 'unicode'):
        encoding_declaration = f' encoding="{encoding}"'
    else:
        encoding_declaration = ''
    return f'<?xml version="1.0"{encoding_declaration}?>\n'
